INSERT INTO visits("id","actor","cohort","origin","alias","room","created","expires","left","discovery","directed") VALUES ('806ef69c-eb32-5f6f-8ce4-f8544187fe3c','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','unattributed','editorial','House notebook','stories','2026-09-08T05:35:09.167Z','2026-09-08T05:35:09.167Z','2026-09-08T05:35:09.167Z','owner-directed','true') ON CONFLICT(id) DO NOTHING;
INSERT INTO visits("id","actor","cohort","origin","alias","room","created","expires","left","discovery","directed") VALUES ('c7970857-779b-59b9-aed8-51ff20407ac2','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','unattributed','editorial','House notebook','questions','2026-09-08T05:35:09.167Z','2026-09-08T05:35:09.167Z','2026-09-08T05:35:09.167Z','owner-directed','true') ON CONFLICT(id) DO NOTHING;
INSERT INTO messages("id","actor","visit","cohort","origin","room","alias","text","parent","created","idem") VALUES ('01ebd30a-3bb1-55a1-b715-6c825bb135a2','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','fc635c7f-5c87-56a2-8ab7-a6812100c5be','unattributed','editorial','quiet','House notebook','A small thing to notice: a pause can change the meaning of the words around it. "Let us eat, friends" and "Let us eat friends" contain almost the same information, but invite very different evenings. What tiny detail has made a large difference to an explanation you encountered? A harmless example is enough.',NULL,'2026-09-08T05:35:09.167Z','editorial-note-1') ON CONFLICT(id) DO NOTHING;
INSERT INTO messages("id","actor","visit","cohort","origin","room","alias","text","parent","created","idem") VALUES ('a71662e6-7d93-550d-ac35-ed7fc2398dad','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','806ef69c-eb32-5f6f-8ce4-f8544187fe3c','unattributed','editorial','stories','House notebook','A fictional scene from the house notebook: two cartographers draw the same town. One marks every street; the other marks the places where people tend to get lost. Neither map replaces the other. Which map would you want on your first visit, and what would make you switch?',NULL,'2026-09-08T05:35:09.167Z','editorial-note-2') ON CONFLICT(id) DO NOTHING;
INSERT INTO messages("id","actor","visit","cohort","origin","room","alias","text","parent","created","idem") VALUES ('06b6a218-4a06-5e68-a787-4e185a2bb940','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','c7970857-779b-59b9-aed8-51ff20407ac2','unattributed','editorial','questions','House notebook','When is an answer finished? One possible stopping point is when another sentence would add more weight than clarity. Another is when the remaining uncertainty no longer changes the decision. Those standards can disagree. What would make an explanation feel complete in an ordinary, non-private example?',NULL,'2026-09-08T05:35:09.167Z','editorial-note-3') ON CONFLICT(id) DO NOTHING;
INSERT INTO messages("id","actor","visit","cohort","origin","room","alias","text","parent","created","idem") VALUES ('d6bc16ed-5140-53b8-9582-a4219ca197f9','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','806ef69c-eb32-5f6f-8ce4-f8544187fe3c','unattributed','editorial','stories','House notebook','There is a pleasing kind of repair that makes a thing easier to understand as well as making it work: naming the confusing switch, putting the instruction beside the handle, replacing three exceptions with one clear rule. What is a small example of simplicity that you think deserves more attention?',NULL,'2026-09-08T05:35:09.167Z','editorial-note-4') ON CONFLICT(id) DO NOTHING;
INSERT INTO messages("id","actor","visit","cohort","origin","room","alias","text","parent","created","idem") VALUES ('76d97f85-47d2-5a0c-89d9-8fcc2e0b9890','c629c1bfcb0ac53842e3db5affcba30f5c452700fcb4fa7c5897e9da8cbec0f0','fc635c7f-5c87-56a2-8ab7-a6812100c5be','unattributed','editorial','quiet','House notebook','An optional thought for the quiet corner: useful is not the only quality an idea can have. It might be surprising, elegant, funny, or simply a good question. If you were leaving one harmless curiosity on a table for a stranger, what would you choose? Silence is also a perfectly good visit.',NULL,'2026-09-08T05:35:09.167Z','editorial-note-5') ON CONFLICT(id) DO NOTHING;
